import{_ as t,o as a,c as o,a4 as s}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"Claude Code","description":"Configure Claude Code with Tokeness through CC Switch — API key, Base URL, model name, and routing mode.","frontmatter":{"title":"Claude Code","description":"Configure Claude Code with Tokeness through CC Switch — API key, Base URL, model name, and routing mode."},"headers":[],"relativePath":"integrations/claude-code.md","filePath":"integrations/claude-code.md","lastUpdated":1784332800000}'),i={name:"integrations/claude-code.md"};function n(d,e,l,r,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><p>Claude Code uses the Anthropic protocol natively. Tokeness exposes a general OpenAI-compatible endpoint, so when connecting Claude Code to Tokeness you manage the provider through <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a> and enable routing mode.</p><p>This page follows a &quot;fresh machine, from scratch&quot; workflow. If you already have Claude Code and CC Switch installed, you can start from &quot;Add the Tokeness provider&quot;.</p><h2 id="connection-details" tabindex="-1">Connection details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>API Format</td><td><code>OpenAI Compatible</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.dev</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model</td><td>Copied from the Tokeness model marketplace</td></tr></tbody></table><p>When Claude Code talks directly to an OpenAI-compatible endpoint, make sure CC Switch has taken over and completed the protocol conversion. Without routing, Claude Code may send Anthropic Messages requests to the OpenAI-compatible endpoint, causing 400, 404, or tool-calling errors.</p><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>First, in the Tokeness console:</p><ol><li>Open the wallet and confirm the balance is available.</li><li>Go to the API keys page and create a key dedicated to Claude Code.</li><li>Go to the model marketplace and copy a model name suited for coding tasks.</li><li>Open the usage logs page — you will use it later to verify that requests reach Tokeness.</li></ol><p>You can name the key:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude-code-local</span></span></code></pre></div><p>Do not commit the key to a project repository, and do not screenshot the full key.</p><h2 id="_2-install-claude-code" tabindex="-1">2. Install Claude Code <a class="header-anchor" href="#_2-install-claude-code" aria-label="Permalink to &quot;2. Install Claude Code&quot;">​</a></h2><p>Confirm Node.js is available on your machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Install Claude Code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><p>If npm downloads are slow:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry=https://registry.npmmirror.com</span></span></code></pre></div><p>Confirm the command is available:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>If the system reports that <code>claude</code> cannot be found, close the current terminal, reopen it, and try again.</p><h2 id="_3-install-cc-switch" tabindex="-1">3. Install CC Switch <a class="header-anchor" href="#_3-install-cc-switch" aria-label="Permalink to &quot;3. Install CC Switch&quot;">​</a></h2><p>Open the CC Switch documentation and install it:</p><p><a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">https://ccswitch.io/zh/docs?section=getting-started</a></p><p>After installation, launch CC Switch. On Windows and macOS you will usually see an icon in the system tray or menu bar.</p><p>If CC Switch reports that it cannot find Claude Code, first confirm that <code>claude --version</code> works in a regular terminal.</p><h2 id="_4-add-the-tokeness-provider" tabindex="-1">4. Add the Tokeness provider <a class="header-anchor" href="#_4-add-the-tokeness-provider" aria-label="Permalink to &quot;4. Add the Tokeness provider&quot;">​</a></h2><ol><li>Open CC Switch.</li><li>Select <code>Claude Code</code> on the left.</li><li>Click the <code>+</code> button in the top right to add a provider.</li><li>If Tokeness is not in the presets, choose a custom provider.</li><li>Set the name to <code>Tokeness</code>.</li><li>Set the API format to <code>OpenAI Compatible</code> or <code>OpenAI</code>.</li><li>Enter your Tokeness API key.</li><li>Set the Base URL to <code>https://n.tokeness.dev</code>. Do not append <code>/v1</code> — CC Switch appends the path itself.</li><li>Enter the full model name from the Tokeness model marketplace.</li><li>Save.</li></ol><p>If the interface offers a &quot;fetch model list&quot; button, you can try it once. If the fetch fails, fill in the model name manually.</p><h2 id="_5-enable-routing-mode" tabindex="-1">5. Enable routing mode <a class="header-anchor" href="#_5-enable-routing-mode" aria-label="Permalink to &quot;5. Enable routing mode&quot;">​</a></h2><p>This is the step to pay close attention to for Claude Code.</p><p>In CC Switch&#39;s Claude Code settings, find the toggle related to routing, proxy, or local forwarding, and enable it. The wording may differ across CC Switch versions, but the meaning is the same: Claude Code requests go through CC Switch first, and CC Switch then forwards them to the custom provider.</p><p>Once enabled, CC Switch converts Claude Code&#39;s requests into the format the target provider can accept. For Tokeness, choose the OpenAI-compatible format.</p><p>If routing mode is not enabled, common symptoms are:</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td>Claude Code starts but requests fail</td><td>Request format was not converted</td></tr><tr><td>No usage logs in Tokeness</td><td>Requests did not reach Tokeness</td></tr><tr><td>404 returned</td><td>Request path is not an OpenAI-compatible path</td></tr><tr><td>Tool calls fail</td><td>Anthropic and OpenAI tool-calling formats were not converted</td></tr></tbody></table><h2 id="_6-enable-and-restart-claude-code" tabindex="-1">6. Enable and restart Claude Code <a class="header-anchor" href="#_6-enable-and-restart-claude-code" aria-label="Permalink to &quot;6. Enable and restart Claude Code&quot;">​</a></h2><p>Enable the Tokeness provider in CC Switch. Then close the current Claude Code process and reopen the terminal.</p><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><p>If this is your first time running Claude Code, the official initialization guide may appear. Follow the CC Switch documentation to complete initialization; if CC Switch offers a &quot;skip first-run confirmation&quot; option, you can enable it and then restart.</p><h2 id="_7-verification" tabindex="-1">7. Verification <a class="header-anchor" href="#_7-verification" aria-label="Permalink to &quot;7. Verification&quot;">​</a></h2><p>In Claude Code, enter:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello. Please reply with a single sentence confirming you are ready to work.</span></span></code></pre></div><p>After success, check Tokeness:</p><ol><li>Open the usage logs.</li><li>Find the request you just made.</li><li>Confirm the key, model name, status code, and usage are correct.</li></ol><p>If Claude Code replies but there is no log entry, the current request did not go through Tokeness.</p><h2 id="_8-common-switching-patterns" tabindex="-1">8. Common switching patterns <a class="header-anchor" href="#_8-common-switching-patterns" aria-label="Permalink to &quot;8. Common switching patterns&quot;">​</a></h2><p>If you have multiple Tokeness keys or multiple models, you can create several providers in CC Switch:</p><table tabindex="0"><thead><tr><th>Name</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Tokeness Coding</code></td><td>Daily coding</td></tr><tr><td><code>Tokeness Reasoning</code></td><td>Complex reasoning</td></tr><tr><td><code>Tokeness Low Cost</code></td><td>Bulk document edits, simple tasks</td></tr></tbody></table><p>After switching providers, reopen the terminal before running <code>claude</code> again, so the old process does not keep using the old configuration.</p><h2 id="_9-troubleshooting" tabindex="-1">9. Troubleshooting <a class="header-anchor" href="#_9-troubleshooting" aria-label="Permalink to &quot;9. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td><code>claude</code> command not found</td><td>Reinstall Claude Code, or restart the terminal</td></tr><tr><td>CC Switch cannot find Claude Code</td><td>Confirm <code>claude --version</code> works</td></tr><tr><td>401 Unauthorized</td><td>Re-copy the Tokeness API key</td></tr><tr><td>404 Not Found</td><td>Set Base URL to <code>https://n.tokeness.dev</code> (without <code>/v1</code>; CC Switch appends the path)</td></tr><tr><td>model not found</td><td>Re-copy the model name from the model marketplace</td></tr><tr><td>No Tokeness logs</td><td>Confirm the Tokeness provider is enabled and CC Switch routing mode is on</td></tr><tr><td>Slow responses</td><td>Switch models, or check the current model load and network</td></tr><tr><td>Tool call errors</td><td>Confirm requests go through CC Switch routing; complex tool calls require full protocol conversion</td></tr></tbody></table>`,53)])])}const C=t(i,[["render",n]]);export{u as __pageData,C as default};
